"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * LIVE ACTIVITY: one pill for whatever is happening now
 *
 *   arrive    the pill opens out of nothing when an activity
 *             starts and folds away when it's cleared
 *   update    the same activity morphs in place: its label
 *             letter by letter, its progress ring filling, its
 *             figure rolling
 *   switch    a different activity blurs in over the last while
 *             the pill reshapes to fit it
 *   expand    tap it and the pill itself grows into a panel
 *             (size and corners easing together): title, a
 *             progress bar, steps that tick themselves off, and
 *             actions. Escape or a tap outside folds it back
 *   done      the spinner blurs into a check that draws itself;
 *             error, into an alert
 *
 * Put it where activity belongs (top of the app, over a
 * composer); it never covers what it's about.
 * ───────────────────────────────────────────────────────── */

export type LiveActivityStatus = "running" | "done" | "error";

export interface LiveActivityStep {
  label: string;
  done?: boolean;
}

export interface LiveActivityAction {
  label: string;
  onClick: () => void;
  primary?: boolean;
}

export interface LiveActivityData {
  /** A new id is a different activity (it blurs in); the same id updates in place. */
  id: string;
  /** In the pill, e.g. "Editing 3 files". */
  label: string;
  status?: LiveActivityStatus;
  /** 0 to 1: a ring in the pill and a bar in the panel. */
  progress?: number;
  /** A figure at the pill's end, e.g. elapsed seconds. */
  count?: { value: number; format?: Intl.NumberFormatOptions; suffix?: string };
  icon?: React.ReactNode;
  /** The panel's heading; defaults to the label. */
  title?: string;
  /** A line under it. */
  detail?: string;
  steps?: LiveActivityStep[];
  actions?: LiveActivityAction[];
}

export interface LiveActivityProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "children"
> {
  activity: LiveActivityData | null;
  expanded?: boolean;
  defaultExpanded?: boolean;
  onExpandedChange?: (expanded: boolean) => void;
  /** The panel's width when expanded. */
  panelWidth?: number;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const MORPH = 480;
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 240ms ${EASE}, transform 360ms ${EASE}, filter 240ms ${EASE}`,
});

/** Spinner, check or alert in one slot, trading places through a blur. */
function StatusMark({
  status,
  icon,
  reduced,
  size = 16,
}: {
  status: LiveActivityStatus;
  icon?: React.ReactNode;
  reduced: boolean;
  size?: number;
}) {
  return (
    <span
      aria-hidden="true"
      className="relative flex shrink-0 items-center justify-center"
      style={{ width: size, height: size }}
    >
      <span
        className="absolute inset-0 flex items-center justify-center text-muted-foreground [&_svg]:size-full"
        style={swap(status === "running", reduced)}
      >
        {icon ?? (
          <span
            className={`size-[85%] rounded-full border-[1.5px] border-current/30 border-t-current ${status === "running" ? "animate-spin" : ""} motion-reduce:animate-none`}
          />
        )}
      </span>
      <span
        className="absolute inset-0 text-emerald-600"
        style={swap(status === "done", reduced)}
      >
        <svg viewBox="0 0 16 16" fill="none" className="size-full">
          <path
            d="M3.5 8.5 6.5 11.5 12.5 4.5"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
            pathLength={1}
            strokeDasharray={1}
            style={{
              strokeDashoffset: status === "done" ? 0 : 1,
              transition: reduced
                ? "none"
                : `stroke-dashoffset 420ms ${EASE} 120ms`,
            }}
          />
        </svg>
      </span>
      <span
        className="absolute inset-0 text-red-500"
        style={swap(status === "error", reduced)}
      >
        <svg viewBox="0 0 16 16" fill="none" className="size-full">
          <circle
            cx="8"
            cy="8"
            r="6.25"
            stroke="currentColor"
            strokeWidth="1.5"
          />
          <path
            d="M8 4.75v3.75M8 11h.01"
            stroke="currentColor"
            strokeWidth="1.6"
            strokeLinecap="round"
          />
        </svg>
      </span>
    </span>
  );
}

function Ring({ value, reduced }: { value: number; reduced: boolean }) {
  const c = 2 * Math.PI * 6;
  return (
    <svg
      viewBox="0 0 16 16"
      aria-hidden="true"
      className="size-4 shrink-0 -rotate-90 text-primary"
    >
      <circle
        cx="8"
        cy="8"
        r="6"
        fill="none"
        stroke="currentColor"
        strokeOpacity="0.18"
        strokeWidth="2"
      />
      <circle
        cx="8"
        cy="8"
        r="6"
        fill="none"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeDasharray={c}
        style={{
          strokeDashoffset: c * (1 - Math.min(1, Math.max(0, value))),
          transition: reduced ? "none" : `stroke-dashoffset 500ms ${EASE}`,
        }}
      />
    </svg>
  );
}

export function LiveActivity({
  activity,
  expanded: expandedProp,
  defaultExpanded = false,
  onExpandedChange,
  panelWidth = 320,
  className = "",
  ...props
}: LiveActivityProps) {
  const reduced = useReducedMotion();
  const panelId = React.useId();
  const [ownExpanded, setOwnExpanded] = React.useState(defaultExpanded);
  // Keep the last activity while the pill folds away, so it doesn't empty as it goes.
  const [last, setLast] = React.useState(activity);
  if (activity && activity !== last) setLast(activity);
  const shown = activity ?? last;
  const present = Boolean(activity);
  // A cleared activity resets the panel, so the next one starts as a pill.
  if (!activity && ownExpanded) setOwnExpanded(false);
  const expanded = (expandedProp ?? ownExpanded) && present;
  const status = shown?.status ?? "running";

  const rootRef = React.useRef<HTMLDivElement>(null);
  const compactRef = React.useRef<HTMLDivElement>(null);
  const panelRef = React.useRef<HTMLDivElement>(null);
  const triggerRef = React.useRef<HTMLButtonElement>(null);
  const [size, setSize] = React.useState({
    compact: { w: 0, h: 36 },
    panel: { w: panelWidth, h: 0 },
  });
  const [enterKey, setEnterKey] = React.useState(shown?.id);

  const setExpanded = React.useCallback(
    (next: boolean) => {
      if (expandedProp === undefined) setOwnExpanded(next);
      onExpandedChange?.(next);
    },
    [expandedProp, onExpandedChange],
  );

  // Both faces are measured as they are; the surface eases between their sizes.
  React.useLayoutEffect(() => {
    const c = compactRef.current;
    const p = panelRef.current;
    if (!c || !p) return;
    const measure = () =>
      setSize((s) => {
        const next = {
          compact: { w: c.offsetWidth, h: c.offsetHeight },
          panel: { w: p.offsetWidth, h: p.offsetHeight },
        };
        return s.compact.w === next.compact.w &&
          s.compact.h === next.compact.h &&
          s.panel.w === next.panel.w &&
          s.panel.h === next.panel.h
          ? s
          : next;
      });
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(c);
    observer.observe(p);
    return () => observer.disconnect();
  }, []);

  // A different activity blurs in over the last: noted while rendering, animated once it's on screen.
  if (shown && shown.id !== enterKey) setEnterKey(shown.id);
  const blurredIn = React.useRef(enterKey);
  React.useLayoutEffect(() => {
    if (enterKey === blurredIn.current) return;
    blurredIn.current = enterKey;
    const el = compactRef.current;
    if (!el || reduced) return;
    el.animate(
      [
        { opacity: 0, filter: "blur(5px)", transform: "translateY(4px)" },
        { opacity: 1, filter: "blur(0px)", transform: "none" },
      ],
      { duration: 360, easing: EASE },
    );
  }, [enterKey, reduced]);

  // Escape or a tap outside folds the panel back into the pill.
  React.useEffect(() => {
    if (!expanded) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== "Escape") return;
      setExpanded(false);
      triggerRef.current?.focus();
    };
    const onDown = (e: PointerEvent) => {
      if (!rootRef.current?.contains(e.target as Node)) setExpanded(false);
    };
    window.addEventListener("keydown", onKey);
    window.addEventListener("pointerdown", onDown);
    return () => {
      window.removeEventListener("keydown", onKey);
      window.removeEventListener("pointerdown", onDown);
    };
  }, [expanded, setExpanded]);

  const w = !present ? 0 : expanded ? size.panel.w : size.compact.w;
  const h = !present
    ? size.compact.h
    : expanded
      ? size.panel.h
      : size.compact.h;
  const progress = shown?.progress;
  const steps = shown?.steps ?? [];
  const doneSteps = steps.filter((s) => s.done).length;

  return (
    <div
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <div
        className="relative overflow-hidden bg-popover text-popover-foreground shadow-[0_0_0_1px_var(--border)]"
        style={{
          width: w,
          height: h,
          borderRadius: expanded ? 22 : h / 2,
          opacity: present ? 1 : 0,
          transform: present ? "none" : "scale(0.85)",
          transition: reduced
            ? "none"
            : `width ${MORPH}ms ${EASE}, height ${MORPH}ms ${EASE}, border-radius ${MORPH}ms ${EASE}, opacity 260ms ${EASE}, transform ${MORPH}ms ${EASE}`,
        }}
      >
        {/* The pill's face. */}
        <div
          className="absolute left-0 top-0"
          style={{
            opacity: expanded ? 0 : 1,
            filter: expanded ? "blur(4px)" : "none",
            pointerEvents: expanded ? "none" : "auto",
            transition: reduced
              ? "none"
              : `opacity ${expanded ? 140 : 300}ms ${EASE}, filter 300ms ${EASE}`,
          }}
        >
          <div ref={compactRef} className="w-max">
            <button
              ref={triggerRef}
              type="button"
              aria-expanded={expanded}
              aria-controls={panelId}
              inert={!present || expanded}
              onClick={() => setExpanded(true)}
              className="cursor-pointer flex h-9 items-center gap-2 whitespace-nowrap rounded-full pl-2.5 pr-3 text-[13px] font-medium focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/40"
            >
              {/* With progress, the ring is the mark; it hands over to the check when it's done. */}
              <span className="relative flex size-4 shrink-0 items-center justify-center">
                <span
                  className="absolute inset-0"
                  style={swap(
                    progress === undefined || status !== "running",
                    reduced,
                  )}
                >
                  <StatusMark
                    status={status}
                    icon={shown?.icon}
                    reduced={reduced}
                  />
                </span>
                <span
                  className="absolute inset-0"
                  style={swap(
                    progress !== undefined && status === "running",
                    reduced,
                  )}
                >
                  <Ring value={progress ?? 0} reduced={reduced} />
                </span>
              </span>
              <TextMorph>{shown?.label ?? ""}</TextMorph>
              {shown?.count && (
                <span className="text-[12px] font-normal tabular-nums text-muted-foreground">
                  <NumberRoll
                    value={shown.count.value}
                    format={shown.count.format}
                    suffix={shown.count.suffix}
                    duration={600}
                  />
                </span>
              )}
            </button>
          </div>
        </div>

        {/* The panel the pill grows into. */}
        <div
          className="absolute left-0 top-0"
          // The face that isn't showing never catches the pointer.
          style={{
            opacity: expanded ? 1 : 0,
            filter: expanded ? "none" : "blur(4px)",
            pointerEvents: expanded ? "auto" : "none",
            transition: reduced
              ? "none"
              : `opacity ${expanded ? `300ms ${EASE} 120ms` : `120ms ${EASE}`}, filter 300ms ${EASE}`,
          }}
        >
          <div
            ref={panelRef}
            id={panelId}
            role="group"
            aria-label={shown?.title ?? shown?.label}
            inert={!expanded}
            className="p-4"
            style={{ width: `min(${panelWidth}px, calc(100vw - 24px))` }}
          >
            <div className="flex items-start gap-2.5">
              <span className="mt-px">
                <StatusMark
                  status={status}
                  icon={shown?.icon}
                  reduced={reduced}
                  size={18}
                />
              </span>
              <div className="min-w-0 flex-1">
                <p className="text-[14px] font-medium leading-snug text-foreground">
                  <TextMorph animateWidth={false}>
                    {shown?.title ?? shown?.label ?? ""}
                  </TextMorph>
                </p>
                {shown?.detail && (
                  <p className="mt-0.5 text-[12.5px] leading-snug text-muted-foreground">
                    {shown.detail}
                  </p>
                )}
              </div>
              {shown?.count && (
                <span className="shrink-0 text-[12.5px] tabular-nums text-muted-foreground">
                  <NumberRoll
                    value={shown.count.value}
                    format={shown.count.format}
                    suffix={shown.count.suffix}
                    duration={600}
                  />
                </span>
              )}
            </div>

            {progress !== undefined && (
              <div className="mt-3.5">
                <div className="h-1.5 overflow-hidden rounded-full bg-muted">
                  <div
                    className={`h-full rounded-full ${status === "error" ? "bg-red-500" : status === "done" ? "bg-emerald-500" : "bg-primary"}`}
                    style={{
                      width: `${Math.round(Math.min(1, Math.max(0, progress)) * 100)}%`,
                      transition: reduced
                        ? "none"
                        : `width 500ms ${EASE}, background-color 300ms`,
                    }}
                  />
                </div>
                <p className="mt-1.5 flex justify-between text-[11.5px] tabular-nums text-muted-foreground">
                  <span>
                    {steps.length
                      ? `${doneSteps} of ${steps.length} steps`
                      : ""}
                  </span>
                  <NumberRoll
                    value={Math.min(1, Math.max(0, progress))}
                    format={{ style: "percent" }}
                    duration={500}
                  />
                </p>
              </div>
            )}

            {steps.length > 0 && (
              <ul className="mt-3 space-y-1.5">
                {steps.map((s, i) => {
                  const current =
                    !s.done &&
                    steps.slice(0, i).every((x) => x.done) &&
                    status === "running";
                  return (
                    <li
                      key={s.label}
                      className={`flex items-center gap-2 text-[12.5px] transition-colors duration-300 ${s.done ? "text-muted-foreground" : current ? "text-foreground" : "text-muted-foreground/70"}`}
                    >
                      <StatusMark
                        status={
                          s.done ? "done" : current ? "running" : "running"
                        }
                        icon={
                          !s.done && !current ? (
                            <span className="size-[60%] rounded-full border border-current/40" />
                          ) : undefined
                        }
                        reduced={reduced}
                        size={14}
                      />
                      {s.label}
                    </li>
                  );
                })}
              </ul>
            )}

            {shown?.actions && shown.actions.length > 0 && (
              <div className="mt-4 flex justify-end gap-2">
                {shown.actions.map((a) => (
                  <button
                    key={a.label}
                    type="button"
                    onClick={a.onClick}
                    className={`cursor-pointer h-8 rounded-full px-3.5 text-[12.5px] font-medium transition-colors ${FOCUS} ${
                      a.primary
                        ? "bg-primary text-primary-foreground hover:bg-primary/90"
                        : "text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent"
                    }`}
                  >
                    {a.label}
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Announce what changed in words, never the ticking figures. */}
      <p role="status" aria-live="polite" className="sr-only">
        {activity
          ? `${activity.label}${activity.status === "done" ? ", done" : activity.status === "error" ? ", failed" : ""}`
          : ""}
      </p>
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

